package agentusageview

import (
	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/config"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// sessionRow is one table row. project is computed once, in Update, so a Cell
// never touches the file system or the environment.
type sessionRow struct {
	agentusage.Session
	project string // theme.FoldHome(Project), or "-" when unknown
}

// sessionListLoadedMsg carries one listing. gen drops an answer to a read that
// a newer one has superseded.
type sessionListLoadedMsg struct {
	gen     int
	root    string
	listing agentusage.Listing
	err     error
}

// sessionUsageLoadedMsg carries one parsed session. gen is agentGen at the time
// the parse started: it drops the answer for a session left or re-read since.
type sessionUsageLoadedMsg struct {
	gen   int
	usage agentusage.Usage
	err   error
}

// level is the screen on view: the sessions, or the agents of one session.
type level int

const (
	levelSessions level = iota
	levelAgents
)

// Model is the agent usage view.
type Model struct {
	table   datatable.Model[sessionRow]
	spinner spinner.Model
	footer  sharedcomponents.FooterMessage

	// level says which table is on screen. The sessions table keeps its cursor
	// and filter while the agents level is open.
	level level
	// agentTable lists the agents of open.
	agentTable datatable.Model[agentRow]
	open       agentusage.Session
	// usage is the last parse of open, kept for what the footer says about it.
	usage agentusage.Usage
	// agentGen numbers the parses, as gen numbers the listings.
	agentGen      int
	agentsLoading bool
	// agentsErr says the most recent parse failed (a state, like loadErr).
	agentsErr bool
	// width and height are the last viewport size, for both tables.
	width, height int

	// gen numbers the reads; only the answer to the latest one is kept.
	gen     int
	loading bool
	// loadErr says the most recent read failed. It is a state rather than a
	// timed message so the empty-listing sentence cannot take its place.
	loadErr bool
	// root is the projects directory the last successful read listed.
	root    string
	omitted int
}

// New builds the view with its first read pending.
func New(_ *config.Config) Model {
	sp := spinner.New()
	sp.Spinner = spinner.Dot
	sp.Style = theme.SpinnerStyle()

	return Model{
		loading: true,
		spinner: sp,
		table: datatable.New(datatable.Config[sessionRow]{
			Columns: sessionColumns(),
			// The listing arrives newest first, which is the order wanted.
			SortColumn: -1,
		}),
		agentTable: datatable.New(datatable.Config[agentRow]{
			Columns: agentColumns(),
			// Opens as the tree (orchestrator, then sub-agents); `.` sorts by Total.
			SortColumn: -1,
		}),
	}
}

// Init starts the first read and the spinner.
func (m Model) Init() tea.Cmd {
	cmds := []tea.Cmd{listSessionsCmd(m.gen), m.spinner.Tick}
	if m.level == levelAgents {
		cmds = append(cmds, parseSessionCmd(m.agentGen, m.open.Parent))
	}
	return tea.Batch(cmds...)
}
package agentusageview

import (
	"log"

	"github.com/charmbracelet/bubbles/spinner"
	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/agentusage"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// Update handles messages.
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		return m.handleResize(msg)
	case sessionListLoadedMsg:
		return m.handleListLoaded(msg)
	case sessionUsageLoadedMsg:
		return m.handleUsageLoaded(msg)
	case spinner.TickMsg:
		return m.handleSpinnerTick(msg)
	case tea.KeyMsg:
		return m.handleKey(msg)
	}
	m.footer.Handle(msg)
	return m, nil
}

// handleResize sizes both tables, so going back from the agents level finds the
// sessions table already fitted. The full viewport width, borders included
// (Rule 116).
func (m Model) handleResize(msg tea.WindowSizeMsg) (tea.Model, tea.Cmd) {
	m.width, m.height = msg.Width, max(msg.Height-1, 1)
	m.table.Resize(m.width, m.height)
	m.agentTable.Resize(m.width, m.height)
	return m, nil
}

// handleListLoaded takes a listing, or ignores one from a superseded read.
// A failed read keeps the rows already shown: they are dated, not wrong.
func (m Model) handleListLoaded(msg sessionListLoadedMsg) (tea.Model, tea.Cmd) {
	if msg.gen != m.gen {
		return m, nil
	}
	m.loading = false
	if msg.err != nil {
		// The error can name a path; it is logged, never shown (Rule 128).
		log.Printf("ERROR [agentusageview] list sessions: %v", msg.err)
		m.loadErr = true
		return m, nil
	}
	m.loadErr = false
	m.root = msg.root
	m.omitted = msg.listing.Omitted
	m.table.SetItems(rowsOf(msg))
	return m, nil
}

// rowsOf folds each project once, so no Cell does it per frame.
func rowsOf(msg sessionListLoadedMsg) []sessionRow {
	rows := make([]sessionRow, len(msg.listing.Sessions))
	for i, s := range msg.listing.Sessions {
		project := noProject
		if s.Project != "" {
			project = theme.FoldHome(s.Project)
		}
		rows[i] = sessionRow{Session: s, project: project}
	}
	return rows
}

// handleSpinnerTick advances the spinner only while a read or a parse is in
// flight, so the chain ends with the load.
func (m Model) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
	if !m.loading && !m.agentsLoading {
		return m, nil
	}
	var cmd tea.Cmd
	m.spinner, cmd = m.spinner.Update(msg)
	m.footer.SetSpinnerFrame(m.spinner.View())
	return m, cmd
}

// handleUsageLoaded takes a parsed session, or ignores one for a session that
// was left or re-read since. A failed refresh keeps the rows already shown.
func (m Model) handleUsageLoaded(msg sessionUsageLoadedMsg) (tea.Model, tea.Cmd) {
	if msg.gen != m.agentGen || m.level != levelAgents {
		return m, nil
	}
	m.agentsLoading = false
	if msg.err != nil {
		// The error names the file by base name only; the path stays out.
		log.Printf("ERROR [agentusageview] read session: %v", msg.err)
		m.agentsErr = true
		return m, nil
	}
	return m.withUsage(msg.usage, true), nil // another session is another population
}

// handleKey gives the filter the keyboard first; ctrl+r refreshes the level on
// screen, → and enter open a session, ← and esc go back.
func (m Model) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	if m.InEditMode() {
		return m, m.activeTable(msg)
	}
	key := msg.String()
	if key == "ctrl+r" {
		return m.refresh()
	}
	a := m.availability()
	switch key {
	case "right", "enter":
		return m.guard(a.Open, m.openSelected)
	case "left", "esc":
		// Silent at the top level: a stray esc is not worth a footer line.
		if a.Close.Enabled() {
			return m.closeAgents()
		}
	case ".":
		if m.level == levelAgents {
			return m.cycleAgentSort(msg)
		}
	}
	return m, m.activeTable(msg)
}

// agentsTree reports whether the agents table shows the tree: no sort active.
func (m Model) agentsTree() bool {
	column, _ := m.agentTable.SortState()
	return column < 0
}

// cycleAgentSort hands `.` to the agents table, then rebuilds the rows so the
// branches follow the new order: a sorted list is flat, a branch there would
// lie about who is whose child.
func (m Model) cycleAgentSort(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	selected, hadSelection := m.selectedAgentKey()
	cmd := m.agentTable.Update(msg)
	m.agentTable.SetItems(agentRows(m.usage, m.agentsTree()))
	m.agentTable.Remeasure() // the Agent column narrows or widens by the branch
	if hadSelection {
		m.selectAgentKey(selected)
	}
	return m, cmd
}

// activeTable hands a key to the table of the level on screen.
func (m *Model) activeTable(msg tea.KeyMsg) tea.Cmd {
	if m.level == levelAgents {
		return m.agentTable.Update(msg)
	}
	return m.table.Update(msg)
}

// openSelected opens the selected session's agents. The table stays empty,
// headers included, until the parse answers (Rule 139).
func (m Model) openSelected() (tea.Model, tea.Cmd) {
	row, _ := m.table.Selected() // availability checked a row exists
	m.usage = agentusage.Usage{}
	m.level = levelAgents
	m.open = row.Session
	m.agentGen++
	m.agentsLoading, m.agentsErr = true, false
	m.agentTable.FilterBar().ClearSearch() // a filter typed for another session
	m.agentTable.SetItems(nil)
	return m, tea.Batch(parseSessionCmd(m.agentGen, m.open.Parent), m.spinner.Tick)
}

// closeAgents returns to the sessions, cursor and filter as they were. Bumping
// agentGen drops a parse still in flight.
func (m Model) closeAgents() (tea.Model, tea.Cmd) {
	m.level = levelSessions
	m.agentGen++
	m.agentsLoading, m.agentsErr = false, false
	m.usage = agentusage.Usage{}
	m.agentTable.SetItems(nil)
	return m, nil
}

// refresh starts a new read of the level on screen under a new generation.
// The rows stay on screen.
func (m Model) refresh() (tea.Model, tea.Cmd) {
	if m.level == levelAgents {
		m.agentGen++
		m.agentsLoading = true
		return m, tea.Batch(parseSessionCmd(m.agentGen, m.open.Parent), m.spinner.Tick)
	}
	m.gen++
	m.loading = true
	m.loadErr = false
	return m, tea.Batch(listSessionsCmd(m.gen), m.spinner.Tick)
}

// InEditMode tells the router the filter has the keyboard.
func (m Model) InEditMode() bool { return m.activeFilterBar().InEditMode() }

// FilterBarVisible closes the viewport rectangle around the bar.
func (m Model) FilterBarVisible() bool { return m.activeFilterBar().IsVisible() }

// activeFilterBar is the bar of the level on screen; each level has its own.
func (m Model) activeFilterBar() *sharedcomponents.FilterBar {
	if m.level == levelAgents {
		return m.agentTable.FilterBar()
	}
	return m.table.FilterBar()
}
package agentusageview

import (
	"fmt"
	"slices"
	"strings"

	"github.com/anthnel/devdesk/internal/agentusage"
)

// mainKey is the key of the orchestrator, of which a session has one.
const mainKey = "main"

// agentKeys names agents so the same one keeps its key from one rebuild to the
// next: "main" for the orchestrator, "sub:<ID>#n" for a sub-agent, n counting
// the earlier agents that share its ID (an ID is not guaranteed unique). It
// must be given the canonical order (agentRows), never the sorted or filtered
// one: under a sort, two twins would trade keys whenever they trade ranks.
func agentKeys(agents []agentusage.Agent) []string {
	seen := make(map[string]int, len(agents))
	keys := make([]string, len(agents))
	for i, a := range agents {
		if a.Main {
			keys[i] = mainKey
			continue
		}
		keys[i] = fmt.Sprintf("sub:%s#%d", a.ID, seen[a.ID])
		seen[a.ID]++
	}
	return keys
}

// populationOf lists what makes a table "another population" for the column
// widths: which agents it holds, and the models each one names. Counts change
// on every delta and do not count. A type can change too (its meta arrives
// after the transcript) but stays out on purpose: the column is remeasured at
// the next ctrl+r or change of population.
func populationOf(rows []agentRow) []string {
	out := make([]string, len(rows))
	for i, r := range rows {
		out[i] = r.key + "|" + strings.Join(r.Models, ",")
	}
	return out
}

// withUsage shows u in the agents table, keeping the cursor on the agent it was
// on (whatever the filter and the sort do to the order), and clears the
// loading and error states. The columns are remeasured only on a full read or
// when the population changed, so a two-second delta never reshuffles them.
func (m Model) withUsage(u agentusage.Usage, full bool) Model {
	before := populationOf(m.agentTable.Items())
	selected, hadSelection := m.selectedAgentKey()
	cursor := m.agentTable.Cursor()

	rows := agentRows(u, m.agentsTree())
	m.usage = u
	m.agentsLoading, m.agentsErr = false, false
	m.agentTable.SetItems(rows)

	if full || !slices.Equal(before, populationOf(rows)) {
		m.agentTable.Remeasure()
	}
	m.agentTable.SetCursor(cursor) // clamps when the agent vanished
	if hadSelection {
		m.selectAgentKey(selected)
	}
	return m
}

// selectAgentKey moves the cursor onto the visible row with that key, if any.
func (m *Model) selectAgentKey(key string) {
	if i := slices.IndexFunc(m.agentTable.Visible(), func(r agentRow) bool { return r.key == key }); i >= 0 {
		m.agentTable.SetCursor(i)
	}
}

// selectedAgentKey is the key of the row under the cursor.
func (m Model) selectedAgentKey() (string, bool) {
	r, ok := m.agentTable.Selected()
	return r.key, ok
}
package agentusageview

import (
	"fmt"
	"sort"
	"strings"

	"github.com/charmbracelet/lipgloss"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

const (
	// noValue is the dash of a cell with nothing to show.
	noValue = "-"
	// noModel stands for an agent whose transcript named no model.
	noModel = noValue
	// unknownID stands for a sub-agent whose ID is empty, so it cannot be
	// mistaken for the orchestrator, which has no short ID by design.
	unknownID = "?"
	// unknownType stands for a sub-agent whose meta file gave no type.
	unknownType = "unknown"
	// orchestratorLabel is the Agent cell of the main agent.
	orchestratorLabel = "orchestrator"
	// partialMark prefixes an output count that is a floor, not an exact value.
	partialMark = "≥ "
	// stem and lastStem draw the tree branch in front of a sub-agent's type.
	stem     = "├─ "
	lastStem = "└─ "
)

// agentIDPrefix is the shortest agent ID shown.
const agentIDPrefix = 8

// agentRow is one line of the agents table.
type agentRow struct {
	agentusage.Agent
	branch  string // stem, lastStem, or "" (orchestrator, or a sorted list)
	shortID string // ID prefix, distinct within the session; "" for the orchestrator
	share   int    // tenths of a percent of the session total, or noShare
	key     string // identity across rebuilds, see agentKeys
}

// agentRows orders a session's agents (orchestrator, then sub-agents by ID),
// gives each its short ID and share, and draws the branches when tree is true.
// The sort is stable so equal IDs keep their input order.
func agentRows(u agentusage.Usage, tree bool) []agentRow {
	var main, subs []agentusage.Agent
	for _, a := range u.Agents {
		if a.Main {
			main = append(main, a)
		} else {
			subs = append(subs, a)
		}
	}
	sort.SliceStable(subs, func(i, j int) bool { return subs[i].ID < subs[j].ID })

	ordered := append(append([]agentusage.Agent{}, main...), subs...)
	totals := make([]int64, len(ordered))
	for i, a := range ordered {
		totals[i] = a.Tokens.Total()
	}
	mainIdx := -1
	if len(main) > 0 {
		mainIdx = 0
	}
	parts := shares(totals, u.Total().Total(), mainIdx)

	ids := make([]string, len(subs))
	for i, a := range subs {
		ids[i] = a.ID
	}
	short := shortAgentIDs(ids)

	keys := agentKeys(ordered)
	rows := make([]agentRow, 0, len(ordered))
	for i, a := range ordered {
		row := agentRow{Agent: a, share: parts[i], key: keys[i]}
		if !a.Main {
			j := i - len(main)
			row.shortID = short[j]
			if tree {
				row.branch = stem
				if j == len(subs)-1 {
					row.branch = lastStem
				}
			}
		}
		rows = append(rows, row)
	}
	return rows
}

// shortAgentIDs cuts every ID to one common length, the smallest n >=
// agentIDPrefix (in runes) at which all of them differ, capped at each ID's
// own length.
func shortAgentIDs(ids []string) []string {
	if len(ids) == 0 {
		return nil
	}
	longest := 0
	runes := make([][]rune, len(ids))
	for i, id := range ids {
		runes[i] = []rune(id)
		longest = max(longest, len(runes[i]))
	}
	cut := func(n int) []string {
		out := make([]string, len(runes))
		for i, r := range runes {
			out[i] = string(r[:min(n, len(r))])
		}
		return out
	}
	for n := agentIDPrefix; n < longest; n++ {
		seen := make(map[string]bool, len(ids))
		distinct := true
		for _, s := range cut(n) {
			if seen[s] {
				distinct = false
				break
			}
			seen[s] = true
		}
		if distinct {
			return cut(n)
		}
	}
	return cut(longest)
}

// agentColumns describes the agents table. Only Total sorts, largest first;
// without a sort the order is the tree. Columns give way on a narrow terminal
// in this order: Cache write, Cache read, In, Model. The ID never does, so two
// agents of one type stay apart.
func agentColumns() []datatable.Column[agentRow] {
	count := func(title string, width int, tokens func(agentRow) int64) datatable.Column[agentRow] {
		return datatable.Column[agentRow]{
			Title: title, Sizing: datatable.SizingFixed, MinWidth: width,
			Cell:  func(r agentRow) string { return formatTokens(tokens(r)) },
			Style: func(r agentRow) lipgloss.Style { return dimWhen(tokens(r) == 0) },
		}
	}
	in := count("In", 6, func(r agentRow) int64 { return r.Tokens.Input })
	in.Optional = true
	cacheRead := count("Cache read", len("Cache read"), func(r agentRow) int64 { return r.Tokens.CacheRead })
	cacheRead.Optional = true
	cacheWrite := count("Cache write", len("Cache write"), func(r agentRow) int64 { return r.Tokens.CacheWrite })
	cacheWrite.Optional, cacheWrite.DropFirst = true, true
	total := count("Total", 6, func(r agentRow) int64 { return r.Tokens.Total() })
	total.Less = func(a, b agentRow) bool { return a.Tokens.Total() < b.Tokens.Total() }
	total.DescFirst = true

	out := count("Out", 7, nil)
	out.Cell = outCell
	out.Style = func(r agentRow) lipgloss.Style { return dimWhen(r.Tokens.Output == 0) }

	return []datatable.Column[agentRow]{
		{Title: "Agent", Sizing: datatable.SizingContent, MinWidth: 14, Cell: roleCell, Search: agentSearch,
			Style: func(r agentRow) lipgloss.Style { return dimWhen(!r.Main && r.Type == "") }},
		{Title: "ID", Sizing: datatable.SizingContent, MinWidth: agentIDPrefix, Cell: idCell,
			Search: func(r agentRow) string { return r.ID },
			Style:  func(r agentRow) lipgloss.Style { return dimWhen(idCell(r) == noValue || idCell(r) == unknownID) }},
		{Title: "Model", Sizing: datatable.SizingContent, MinWidth: 12, Flex: 2, Optional: true, Cell: modelsCell, Search: modelsCell,
			Style: func(r agentRow) lipgloss.Style { return dimWhen(len(r.Models) == 0) }},
		in, out, cacheRead, cacheWrite, total,
		{Title: "Share", Sizing: datatable.SizingFixed, MinWidth: len("100.0%"), Cell: shareCell,
			Style: func(r agentRow) lipgloss.Style { return dimWhen(r.share <= 0) }},
	}
}

// dimWhen is Rule 122's colour discipline: a zero or a placeholder is dim,
// anything else keeps the default colour.
func dimWhen(dim bool) lipgloss.Style {
	if dim {
		return theme.DimStyle
	}
	return lipgloss.NewStyle()
}

// agentSearch is what `/` matches in the Agent column: the role. The full ID is
// searched through the ID column.
func agentSearch(r agentRow) string { return roleCell(r) }

// idCell is the ID column: the short ID of a sub-agent, a dash for the
// orchestrator, which has none.
func idCell(r agentRow) string {
	switch {
	case r.Main:
		return noValue
	case r.shortID == "":
		return unknownID
	}
	return r.shortID
}

// shareCell is the Share column.
func shareCell(r agentRow) string { return formatShare(r.share) }

// roleCell is the Agent cell: "orchestrator", or the sub-agent's type behind
// its branch.
func roleCell(r agentRow) string {
	if r.Main {
		return orchestratorLabel
	}
	typ := r.Type
	if typ == "" {
		typ = unknownType
	}
	return r.branch + typ
}

// modelsCell lists the models the agent used.
func modelsCell(r agentRow) string {
	if len(r.Models) == 0 {
		return noModel
	}
	return strings.Join(r.Models, ", ")
}

// outCell is the output count. A sub-agent still being written is a floor and
// says so; the orchestrator never does, its transcript is the one being read.
func outCell(r agentRow) string {
	out := formatTokens(r.Tokens.Output)
	if !r.Main && r.PartialOutput() {
		return partialMark + out
	}
	return out
}

// formatTokens renders a count compactly, floored to one decimal: 1099 is
// "1.0k", never "1.1k". From 100 of a unit up the decimal is dropped.
func formatTokens(n int64) string {
	units := []struct {
		size   int64
		suffix string
	}{
		{1_000_000_000_000, "T"}, {1_000_000_000, "B"}, {1_000_000, "M"}, {1_000, "k"},
	}
	for _, u := range units {
		if n < u.size {
			continue
		}
		tenths := n / (u.size / 10) // divide first: n*10 would overflow
		if tenths >= 1000 {
			return fmt.Sprintf("%d%s", tenths/10, u.suffix)
		}
		return fmt.Sprintf("%d.%d%s", tenths/10, tenths%10, u.suffix)
	}
	return fmt.Sprintf("%d", n)
}
