	}
}

func TestOnlyTheFirstFailureOfAStreakIsLogged(t *testing.T) {
	buf := captureLog(t)
	m, _ := atFixture(t)
	fail := func() {
		m.reading = true
		m = feed(t, m, usageDeltaMsg{gen: m.agentGen, err: errors.New("boom")})
	}
	succeed := func() {
		m.reading = true
		m = feed(t, m, runDelta(t, m.agentGen, m.agg.Cursor()))
	}

