	if m.agentsErr {
		t.Error("a successful read ends the failure state")
	}
	fail()
	if n := strings.Count(buf.String(), logTag); n != 2 {
		t.Errorf("a failure after a success is a new streak: %d log lines, want 2", n)
	}
